function pickStrategy({ contentChangesOften, hasSlowDependency, mostlyStaticWithFewWidgets }) {
  if (mostlyStaticWithFewWidgets) return 'islands';
  if (hasSlowDependency) return 'streaming-ssr';
  if (!contentChangesOften) return 'ssg';
  return 'streaming-ssr';
}

